import { useEffect } from 'react';

/**
 * Hook to initialize GeoView maps for the entire page.
 * Should be called once at the app level after DOM is ready.
 * GeoView will automatically scan the DOM for elements with class "geoview-map"
 * and initialize them using their id and data-config attributes.
 */
export const useGeoViewInit = () => {
  useEffect(() => {
    // Wait for DOM to be fully ready and GeoView library to load
    const initGeoView = async () => {
      // Give browser time to render all DOM elements
      await new Promise(resolve => setTimeout(resolve, 100));

      if (!window.cgpv) {
        console.warn('GeoView library not loaded');
        return;
      }

      try {
        // Single init call for entire page - GeoView will find all .geoview-map divs
        await window.cgpv.init();
      } catch (err) {
        console.error('GeoView initialization error:', err);
      }
    };

    initGeoView();
  }, []);
};
